    let id = newId()
    let now = epochNow()
    let stmt =
        bind (db.prepare("INSERT INTO albums (id, title, slug, cover, release_date, created_at) VALUES (?, ?, ?, ?, ?, ?)"))
             [| box id; box create.Title; box create.Slug; optToDb create.Cover; box create.ReleaseDate; box now |]
    {| Stmt = stmt; Id = id; CreatedAt = now |}

let updateAlbum (id: string) (create: AlbumCreate) (db: D1Database) : D1PreparedStatement =
    let now = epochNow()
    bind (db.prepare("UPDATE albums SET title = ?, slug = ?, cover = ?, release_date = ?, updated_at = ? WHERE id = ?"))
         [| box create.Title; box create.Slug; optToDb create.Cover; box create.ReleaseDate; box now; box id |]

let deleteAlbum (id: string) (db: D1Database) : D1PreparedStatement =
